import com.gregtech.gregtech.worldgen.FluidSpringRules;
import com.gregtech.gregtech.worldgen.MineralWorldgenRules;
import java.util.HashSet;
import java.util.Set;

/** Records real core write intents. It does not simulate Minecraft blocks or placement permission. */
public final class WriterProbe {
    private record Cell(int x, int y, int z) {}

    public static void main(String[] args) {
        Set<Cell> ore = new HashSet<>();
        Set<Cell> fluid = new HashSet<>();
        MineralWorldgenRules.bedrockVein(0, 0, -64, 64, bound -> 0, new MineralWorldgenRules.VeinSink() {
            public boolean isBedrockFloor(int x, int y, int z) { return true; }
            public void prepareStone(int x, int y, int z) {}
            public boolean bedrock(int x, int y, int z, boolean small) { return true; }
            public boolean ore(int x, int y, int z, boolean small) { ore.add(new Cell(x, y, z)); return true; }
        });
        FluidSpringRules.carve(0, 0, bound -> 0, new FluidSpringRules.CraterSink() {
            public void filler(int x, int y, int z) {}
            public void fluid(int x, int y, int z) { fluid.add(new Cell(x, -64 + y, z)); }
            public boolean bedrock(int x, int z) { return false; }
            public boolean spring(int x, int z) { return false; }
        });
        Set<Cell> overlap = new HashSet<>(ore);
        overlap.retainAll(fluid);
        int[] smallRequests = {0};
        MineralWorldgenRules.bedrockVein(0, 0, -64, 64, bound -> bound == 6 ? 1 : 0,
                new MineralWorldgenRules.VeinSink() {
                    public boolean isBedrockFloor(int x, int y, int z) { return true; }
                    public void prepareStone(int x, int y, int z) {}
                    public boolean bedrock(int x, int y, int z, boolean small) {
                        if (small) smallRequests[0]++;
                        return true;
                    }
                    public boolean ore(int x, int y, int z, boolean small) { return true; }
                });
        System.out.printf("{\"ore_write_intent_positions\":%d,\"fluid_write_intent_positions\":%d,"
                + "\"overlapping_positions\":%d,\"small_bedrock_requests\":%d}%n",
                ore.size(), fluid.size(), overlap.size(), smallRequests[0]);
    }
}
